package app.studyhub.application; import app.studyhub.api.CourseRequest; import app.studyhub.domain.Course; import app.studyhub.infrastructure.CourseRepository; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional public class CourseService { private final CourseRepository repository; public CourseService(CourseRepository repository){this.repository=repository;} @Transactional(readOnly=true) public List<Course> list(){return repository.findAll();} public Course create(CourseRequest r){Course c=new Course();c.setTitle(r.title());c.setProfessor(r.professor());return repository.save(c);} public void remove(UUID id){repository.deleteById(id);} }
